-- evt:art_of_magic
RegisterEvent(2, "The Art of Magic", function()
    evt.SimpleMessage("THE ART OF MAGIC. 'Every spell is a door, and every door a lock. The novice forces the lock; the master learns the shape of the key. Fire wants feeding, water wants a vessel, air will go where it likes, earth will not go at all. Learn what each wants, and it will come to your hand as a dog comes to its name.' The rest is the Archmage's notes in the margins, in a hand too small to read.")
end, "The Art of Magic")

