-- evt:valve
RegisterEvent(40, "Steam valve", function()
    if not (not (IsAtLeast(MapVar(1), 1))) then
        evt.StatusText("The valve is open as far as it goes; steam hisses in the pipes.", 6)
        evt.SetDoorState(23, DoorAction.Close)
        return
    end
    evt.SetDoorState(7, DoorAction.Open)
    evt.SetDoorState(23, DoorAction.Open)
    SetValue(MapVar(1), 1)
    evt.SimpleMessage("You heave the steam valve round. The pipes knock and hiss along the walls, and from the garden beyond the still comes the crack and drip of thawing ice: the frozen door of the west stair stands open.")
end, "Steam valve")
